#!/usr/bin/env sh
# fetch COMMUNAUTE D'AGGLOMERATION DES 2 BAIES EN MONTREUILLOIS (FR) GTFS -> gtfs.zip. Regenerated by build_repo.py.
URL="https://static.data.gouv.fr/resources/reseau-ca2bm-a-compter-du-1er-juin-2025/20260715-075301/ca2bm-lignes-regulieres-v32-ter-modif-gtfs-gtfs-2026-07-15-09-48-30.zip"
DIR="$(CDPATH= cd "$(dirname "$0")" && pwd)"
echo "GET $URL"
curl -fSL --retry 3 --max-time 300 -o "$DIR/gtfs.zip" "$URL" || { echo "download failed"; exit 1; }
unzip -l "$DIR/gtfs.zip" 2>/dev/null | grep -q stops.txt || { echo "not valid GTFS (no stops.txt)"; exit 2; }
echo "ok: $DIR/gtfs.zip"
